// Report whether the object blueprint (the master copy of the program) for
// 'path' is already resident in memory.  find_object() -- without the load
// flag -- only ever looks the program up in the driver's loaded-object
// table, so this never forces a compile or a load.

int is_blueprint_loaded(string path) {
  if (!path || path == "") return 0;

  // find_object() matches the name exactly as given, so try the spellings
  // the driver itself uses for the same program: with and without the
  // source extension, and the absolute form of a relative path.  The path
  // call_other is guarded by catch(): an object that is not loaded would
  // otherwise error out.
  string *names = ({ path });
  string ext = "";
  if (path[<1..<1] == ".c")
    ext = ".c";
  else if (path[<1..<1] == ".lpc")
    ext = ".lpc";
  if (ext)
    names += ({ path[0..<3 - sizeof(ext)] });
  if (path[0] != '/')
    names += ({ "/" + path });

  foreach (string name in names) {
    if (name == "") continue;
    if (find_object(name)) return 1;
    // __DIR__ is "" for an object loaded through the -ftest runner, so the
    // bare name of a sibling object is relative to the mudlib root.
    if (find_object(__DIR__ + name)) return 1;
  }
  return 0;
}

