// Query the shadow currently attached to `target`, using shadow(target, 0).
//
// The query form of shadow() answers from the point of view of the object
// that calls it: it returns whatever is shadowing `target` *as seen from the
// caller*, which is 0 for anyone who is not that shadow.  Read directly it
// is therefore only ever a self-query.  To see a shadow attached to another
// object, the query has to be asked *through* the object that the shadow is
// really attached to -- a call there is redirected into the shadow, so the
// query runs as the shadow and answers with itself.

object get_active_shadow(object target) {
  object caller = previous_object();
  object shadow;

  if (!objectp(target)) return 0;

  // Called by the shadow itself: it is the object attached to `target`.
  shadow = shadow(caller, 0);
  if (objectp(shadow) && shadow == target) return caller;

  // Called from anywhere else: ask the caller what is shadowing it.  If the
  // caller is itself shadowed, the call is redirected into that shadow, which
  // takes the branch above and hands back the object it is shadowing.
  shadow = shadow(caller, 0);
  if (objectp(shadow)) {
    object attached = shadow->get_active_shadow(target);
    if (objectp(attached)) return attached;
  }

  // No chain leads to `target`; fall back to the plain self-query, which
  // covers the case where the caller is directly shadowing `target`.
  shadow = shadow(target, 0);
  return objectp(shadow) ? shadow : 0;
}

