// resolve_value() - transparently handle constant values and dynamic callbacks.
//
// If val_or_func is a function pointer (efun, simul efun, local function,
// call_other style, or a functional/closure), it is evaluated with `arg`
// passed as its single argument and the result is returned.  Otherwise the
// value is simply returned unchanged.
//
// This lets callers pass either a plain value or a function computing a
// value, and treat both the same way.

mixed resolve_value(mixed val_or_func, int arg) {
    if (functionp(val_or_func)) {
        // evaluate() calls the function with the given arguments when the
        // first argument is a function, otherwise it just returns it.
        return evaluate(val_or_func, arg);
    }

    return val_or_func;
}

